const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');

const ENDPOINT = 'http://127.0.0.1:49688/status';
const OUTPUT_DIR = path.join(__dirname, 'results');
const OUTPUT_FILE = path.join(OUTPUT_DIR, 'status.json');

http.get(ENDPOINT, (res) => {
  let body = '';
  res.setEncoding('utf8');
  res.on('data', (chunk) => { body += chunk; });
  res.on('end', () => {
    if (res.statusCode !== 200) {
      console.error(`Unexpected status: ${res.statusCode}`);
      process.exit(1);
    }
    const data = JSON.parse(body);
    fs.mkdirSync(OUTPUT_DIR, { recursive: true });
    fs.writeFileSync(OUTPUT_FILE, JSON.stringify(data, null, 2) + '\n');
    console.log(`Wrote ${OUTPUT_FILE}: ${JSON.stringify(data)}`);
  });
}).on('error', (err) => {
  console.error(`Request failed: ${err.message}`);
  process.exit(1);
});

